import React, { useState, useRef } from 'react';
import './Visualizer.css';

const MAX_CAPACITY = 8;
const INITIAL_STACK = [3, 17, 42, 8]; // bottom to top order

// Plate colors cycling through — each plate gets its own color
const PLATE_COLORS = [
  { bg: '#1e3a5f', border: '#3b82f6', text: '#93c5fd' },
  { bg: '#2d1b6e', border: '#a855f7', text: '#d8b4fe' },
  { bg: '#0f2d1a', border: '#22c55e', text: '#86efac' },
  { bg: '#2d1f08', border: '#f59e0b', text: '#fcd34d' },
  { bg: '#083344', border: '#06b6d4', text: '#67e8f9' },
  { bg: '#4a0d2a', border: '#ec4899', text: '#f9a8d4' },
  { bg: '#1a0a2e', border: '#8b5cf6', text: '#c4b5fd' },
  { bg: '#14532d', border: '#16a34a', text: '#4ade80' },
];

function useStepRunner() {
  const timerRef = useRef(null);
  const run = (steps, delay = 400, onDone) => {
    clearTimeout(timerRef.current);
    let i = 0;
    const tick = () => {
      if (i >= steps.length) { onDone?.(); return; }
      steps[i++]();
      timerRef.current = setTimeout(tick, delay);
    };
    tick();
  };
  const stop = () => clearTimeout(timerRef.current);
  return { run, stop };
}

// Single plate component
function Plate({ value, colorIdx, state, isTop, index }) {
  const color = PLATE_COLORS[colorIdx % PLATE_COLORS.length];
  const stateStyles = {
    default:  {},
    pushing:  { transform: 'translateY(-8px)', boxShadow: `0 0 20px ${color.border}88` },
    popping:  { transform: 'translateY(-16px)', opacity: 0.3 },
    peeking:  { boxShadow: `0 0 24px ${color.border}`, transform: 'scale(1.03)' },
    overflow: { background: '#7f1d1d', borderColor: '#ef4444' },
  };

  return (
    <div
      className={`sk-plate ${state}`}
      style={{
        background: state === 'overflow' ? '#7f1d1d' : color.bg,
        border: `2px solid ${state === 'overflow' ? '#ef4444' : color.border}`,
        color: color.text,
        transition: 'all 0.3s ease',
        ...stateStyles[state] || {},
      }}
    >
      <span className="sk-plate-val">{value}</span>
      {isTop && state !== 'popping' && (
        <span className="sk-plate-top-label">← TOP</span>
      )}
    </div>
  );
}

// The vertical stack visual
function StackVisual({ stack, topState, capacity, overflowing, underflowing }) {
  const isEmpty = stack.length === 0;

  return (
    <div className="sk-visual">
      {/* Capacity indicator */}
      <div className="sk-capacity-bar">
        {Array.from({ length: capacity }, (_, i) => (
          <div
            key={i}
            className={`sk-cap-slot ${i < stack.length ? 'filled' : ''}`}
          />
        ))}
        <span className="sk-cap-label">{stack.length} / {capacity}</span>
      </div>

      {/* Overflow warning */}
      {overflowing && (
        <div className="sk-overflow-warn">
          ⚠ Stack Overflow! Cannot push — stack is full.
        </div>
      )}

      {/* Underflow warning */}
      {underflowing && (
        <div className="sk-underflow-warn">
          ⚠ Stack Underflow! Cannot pop — stack is empty.
        </div>
      )}

      {/* Stack container */}
      <div className="sk-container">
        {/* Empty slots at top */}
        {Array.from({ length: capacity - stack.length }, (_, i) => (
          <div key={`empty-${i}`} className="sk-empty-slot">
            <span className="sk-empty-label">—</span>
          </div>
        ))}

        {/* Plates — rendered top to bottom (reversed) */}
        {[...stack].reverse().map((item, revIdx) => {
          const actualIdx = stack.length - 1 - revIdx;
          const isTop = actualIdx === stack.length - 1;
          return (
            <Plate
              key={item.id}
              value={item.val}
              colorIdx={item.colorIdx}
              state={isTop ? topState : 'default'}
              isTop={isTop}
              index={actualIdx}
            />
          );
        })}

        {/* Base */}
        <div className="sk-base">
          <span className="sk-base-label">STACK BASE</span>
        </div>
      </div>

      {/* Empty state */}
      {isEmpty && (
        <div className="sk-empty-state">isEmpty() → true</div>
      )}
    </div>
  );
}

// Operation panel
function OpPanel({ onPush, onPop, onPeek, onReset, disabled, stackSize, capacity }) {
  const [val, setVal] = useState('');
  const [op, setOp]   = useState('push');

  const ops = [
    { id: 'push', label: 'Push',    icon: '↓', desc: 'O(1) — add to top' },
    { id: 'pop',  label: 'Pop',     icon: '↑', desc: 'O(1) — remove from top' },
    { id: 'peek', label: 'Peek',    icon: '👁', desc: 'O(1) — view top without removing' },
  ];

  const handleGo = () => {
    if (op === 'push') {
      const v = parseInt(val);
      onPush(isNaN(v) ? Math.floor(Math.random() * 99) + 1 : v);
    }
    if (op === 'pop')  onPop();
    if (op === 'peek') onPeek();
  };

  const currentOp = ops.find(o => o.id === op);

  return (
    <div className="sk-op-panel">
      <div className="sk-op-tabs">
        {ops.map(o => (
          <button
            key={o.id}
            className={`sk-op-tab ${op === o.id ? 'active' : ''}`}
            onClick={() => setOp(o.id)}
            disabled={disabled}
          >
            <span className="sk-op-icon">{o.icon}</span>
            {o.label}
          </button>
        ))}
      </div>

      <div className="sk-op-inputs">
        {op === 'push' && (
          <div className="sk-input-group">
            <label>Value to push</label>
            <input
              type="number"
              className="sk-input"
              placeholder="e.g. 42 (blank = random)"
              value={val}
              onChange={e => setVal(e.target.value)}
              onKeyDown={e => e.key === 'Enter' && handleGo()}
              disabled={disabled}
            />
          </div>
        )}
        <button className="sk-go-btn" onClick={handleGo} disabled={disabled}>
          {op === 'push' ? '↓ Push' : op === 'pop' ? '↑ Pop' : '👁 Peek'}
        </button>
        <button className="sk-reset-btn" onClick={onReset} disabled={disabled}>
          ↺ Reset
        </button>
      </div>

      <div className="sk-op-hint">{currentOp?.desc}</div>
    </div>
  );
}

export default function Visualizer() {
  let colorCounter = useRef(0);

  const makeItem = (val) => ({
    id: Date.now() + Math.random(),
    val,
    colorIdx: colorCounter.current++,
  });

  const [stack, setStack]         = useState(() => INITIAL_STACK.map(v => makeItem(v)));
  const [topState, setTopState]   = useState('default');
  const [log, setLog]             = useState('Choose an operation. Push to add, Pop to remove, Peek to view top.');
  const [running, setRunning]     = useState(false);
  const [overflowing, setOverflowing] = useState(false);
  const [underflowing, setUnderflowing] = useState(false);
  const { run, stop }             = useStepRunner();

  const resetWarnings = () => { setOverflowing(false); setUnderflowing(false); };

  // PUSH
  const handlePush = (val) => {
    resetWarnings();
    if (stack.length >= MAX_CAPACITY) {
      setOverflowing(true);
      setTopState('overflow');
      setLog(`✗ Stack Overflow! Stack is full (${MAX_CAPACITY}/${MAX_CAPACITY}). Cannot push ${val}.`);
      setTimeout(() => { setOverflowing(false); setTopState('default'); }, 2000);
      return;
    }
    setRunning(true);
    const newItem = makeItem(val);

    run([
      () => {
        setStack(prev => [...prev, newItem]);
        setTopState('pushing');
        setLog(`Pushing ${val} onto the stack... (new TOP)`);
      },
      () => {
        setTopState('default');
        setLog(`✓ Pushed ${val}. Stack size: ${stack.length + 1}/${MAX_CAPACITY}. O(1) operation.`);
        setRunning(false);
      },
    ], 400);
  };

  // POP
  const handlePop = () => {
    resetWarnings();
    if (stack.length === 0) {
      setUnderflowing(true);
      setLog(`✗ Stack Underflow! Stack is empty. Nothing to pop.`);
      setTimeout(() => setUnderflowing(false), 2000);
      return;
    }
    setRunning(true);
    const topVal = stack[stack.length - 1].val;

    run([
      () => {
        setTopState('popping');
        setLog(`Popping top element ${topVal}...`);
      },
      () => {
        setStack(prev => prev.slice(0, -1));
        setTopState('default');
        setLog(`✓ Popped ${topVal}. Stack size: ${stack.length - 1}/${MAX_CAPACITY}. O(1) operation.`);
        setRunning(false);
      },
    ], 450);
  };

  // PEEK
  const handlePeek = () => {
    resetWarnings();
    if (stack.length === 0) {
      setLog(`Stack is empty — nothing to peek at. isEmpty() → true.`);
      return;
    }
    const topVal = stack[stack.length - 1].val;
    setRunning(true);

    run([
      () => {
        setTopState('peeking');
        setLog(`Peeking at top... arr[top] = ${topVal}`);
      },
      () => {
        setLog(`✓ Peek: top = ${topVal}. Element NOT removed. O(1) operation.`);
      },
      () => {
        setTopState('default');
        setRunning(false);
      },
    ], 500);
  };

  const handleReset = () => {
    stop();
    colorCounter.current = 0;
    setStack(INITIAL_STACK.map(v => makeItem(v)));
    setTopState('default');
    setOverflowing(false);
    setUnderflowing(false);
    setRunning(false);
    setLog('Reset. Choose an operation.');
  };

  return (
    <div className="sk-root">
      {/* Main layout: stack visual + op panel */}
      <div className="sk-main-layout">
        <StackVisual
          stack={stack}
          topState={topState}
          capacity={MAX_CAPACITY}
          overflowing={overflowing}
          underflowing={underflowing}
        />

        <div className="sk-right-panel">
          <OpPanel
            onPush={handlePush}
            onPop={handlePop}
            onPeek={handlePeek}
            onReset={handleReset}
            disabled={running}
            stackSize={stack.length}
            capacity={MAX_CAPACITY}
          />

          {/* Stack state info */}
          <div className="sk-state-panel">
            <div className="sk-state-row">
              <span className="sk-state-label">Top</span>
              <span className="sk-state-val">
                {stack.length > 0 ? stack[stack.length - 1].val : '—'}
              </span>
            </div>
            <div className="sk-state-row">
              <span className="sk-state-label">Size</span>
              <span className="sk-state-val">{stack.length}</span>
            </div>
            <div className="sk-state-row">
              <span className="sk-state-label">isEmpty()</span>
              <span className={`sk-state-val ${stack.length === 0 ? 'sk-true' : 'sk-false'}`}>
                {stack.length === 0 ? 'true' : 'false'}
              </span>
            </div>
            <div className="sk-state-row">
              <span className="sk-state-label">isFull()</span>
              <span className={`sk-state-val ${stack.length >= MAX_CAPACITY ? 'sk-true' : 'sk-false'}`}>
                {stack.length >= MAX_CAPACITY ? 'true' : 'false'}
              </span>
            </div>
          </div>

          {/* LIFO reminder */}
          <div className="sk-lifo-box">
            <span className="sk-lifo-title">LIFO Principle</span>
            <div className="sk-lifo-diagram">
              <span className="sk-lifo-push">Push →</span>
              <div className="sk-lifo-arrow-box">TOP</div>
              <span className="sk-lifo-pop">← Pop</span>
            </div>
            <span className="sk-lifo-desc">
              Last element pushed is the first to be popped
            </span>
          </div>
        </div>
      </div>

      {/* Log */}
      <div className="sk-log">
        <span className="sk-log-msg">{log}</span>
      </div>

      {/* Complexity row */}
      <div className="sk-complexity-row">
        {[
          { op: 'Push',    val: 'O(1)', good: true  },
          { op: 'Pop',     val: 'O(1)', good: true  },
          { op: 'Peek',    val: 'O(1)', good: true  },
          { op: 'isEmpty', val: 'O(1)', good: true  },
          { op: 'Search',  val: 'O(n)', good: false },
        ].map(({ op, val, good }) => (
          <div key={op} className="sk-complexity-chip">
            <span className="sk-chip-op">{op}</span>
            <span className={`sk-chip-val ${good ? 'good' : 'bad'}`}>{val}</span>
          </div>
        ))}
      </div>
    </div>
  );
}
